PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS lab_companies(id TEXT PRIMARY KEY) STRICT;
CREATE TABLE IF NOT EXISTS lab_branches(companyId TEXT NOT NULL,id TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),PRIMARY KEY(companyId,id),FOREIGN KEY(companyId) REFERENCES lab_companies(id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_actors(companyId TEXT NOT NULL,id TEXT NOT NULL,branchId TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,id),UNIQUE(companyId,id,branchId),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_control(companyId TEXT NOT NULL,branchId TEXT NOT NULL,epoch INTEGER NOT NULL CHECK(epoch>0),periodOpen INTEGER NOT NULL CHECK(periodOpen IN(0,1)),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_stock(companyId TEXT NOT NULL,branchId TEXT NOT NULL,sku TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>=0),reserved INTEGER NOT NULL CHECK(reserved>=0 AND reserved<=qty),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId,sku),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_customers(companyId TEXT NOT NULL,branchId TEXT NOT NULL,id TEXT NOT NULL,balance TEXT NOT NULL CHECK(typeof(balance)='text' AND length(replace(balance,'-','')) BETWEEN 4 AND 21 AND replace(balance,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(balance,'-',''))-length(replace(replace(balance,'-',''),'.',''))=1 AND substr(replace(balance,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(balance,'-',''),'.')=length(replace(balance,'-',''))-2 AND length(balance)-length(replace(balance,'-',''))<=1 AND instr(balance,'-') IN(0,1) AND (substr(replace(balance,'-',''),1,1)!='0' OR instr(replace(balance,'-',''),'.')=2) AND balance!='-0.00'),creditLimit TEXT NOT NULL CHECK(typeof(creditLimit)='text' AND length(replace(creditLimit,'-','')) BETWEEN 4 AND 21 AND replace(creditLimit,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(creditLimit,'-',''))-length(replace(replace(creditLimit,'-',''),'.',''))=1 AND substr(replace(creditLimit,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(creditLimit,'-',''),'.')=length(replace(creditLimit,'-',''))-2 AND length(creditLimit)-length(replace(creditLimit,'-',''))<=1 AND instr(creditLimit,'-') IN(0,1) AND (substr(replace(creditLimit,'-',''),1,1)!='0' OR instr(replace(creditLimit,'-',''),'.')=2) AND creditLimit!='-0.00'),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId,id),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_approvals(companyId TEXT NOT NULL,branchId TEXT NOT NULL,id TEXT NOT NULL,customerId TEXT NOT NULL,allowance TEXT NOT NULL CHECK(typeof(allowance)='text' AND length(replace(allowance,'-','')) BETWEEN 4 AND 21 AND replace(allowance,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(allowance,'-',''))-length(replace(replace(allowance,'-',''),'.',''))=1 AND substr(replace(allowance,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(allowance,'-',''),'.')=length(replace(allowance,'-',''))-2 AND length(allowance)-length(replace(allowance,'-',''))<=1 AND instr(allowance,'-') IN(0,1) AND (substr(replace(allowance,'-',''),1,1)!='0' OR instr(replace(allowance,'-',''),'.')=2) AND allowance!='-0.00'),unused INTEGER NOT NULL CHECK(unused IN(0,1)),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId,id),FOREIGN KEY(companyId,branchId,customerId) REFERENCES lab_customers(companyId,branchId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_coupons(companyId TEXT NOT NULL,branchId TEXT NOT NULL,id TEXT NOT NULL,remaining INTEGER NOT NULL CHECK(remaining>=0),discount TEXT NOT NULL CHECK(typeof(discount)='text' AND length(replace(discount,'-','')) BETWEEN 4 AND 21 AND replace(discount,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(discount,'-',''))-length(replace(replace(discount,'-',''),'.',''))=1 AND substr(replace(discount,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(discount,'-',''),'.')=length(replace(discount,'-',''))-2 AND length(discount)-length(replace(discount,'-',''))<=1 AND instr(discount,'-') IN(0,1) AND (substr(replace(discount,'-',''),1,1)!='0' OR instr(replace(discount,'-',''),'.')=2) AND discount!='-0.00'),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId,id),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_counters(companyId TEXT NOT NULL,branchId TEXT NOT NULL,next INTEGER NOT NULL CHECK(next>0),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_cash(companyId TEXT NOT NULL,branchId TEXT NOT NULL,balance TEXT NOT NULL CHECK(typeof(balance)='text' AND length(replace(balance,'-','')) BETWEEN 4 AND 21 AND replace(balance,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(balance,'-',''))-length(replace(replace(balance,'-',''),'.',''))=1 AND substr(replace(balance,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(balance,'-',''),'.')=length(replace(balance,'-',''))-2 AND length(balance)-length(replace(balance,'-',''))<=1 AND instr(balance,'-') IN(0,1) AND (substr(replace(balance,'-',''),1,1)!='0' OR instr(replace(balance,'-',''),'.')=2) AND balance!='-0.00'),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_operations(companyId TEXT NOT NULL,clientRequestId TEXT NOT NULL,branchId TEXT NOT NULL,actorId TEXT NOT NULL,payloadHash TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL,kind TEXT NOT NULL,PRIMARY KEY(companyId,clientRequestId),FOREIGN KEY(companyId,actorId,branchId) REFERENCES lab_actors(companyId,id,branchId)) STRICT;
CREATE TABLE IF NOT EXISTS lab_orders(companyId TEXT NOT NULL,id TEXT NOT NULL,branchId TEXT NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),total TEXT NOT NULL CHECK(typeof(total)='text' AND length(replace(total,'-','')) BETWEEN 4 AND 21 AND replace(total,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(total,'-',''))-length(replace(replace(total,'-',''),'.',''))=1 AND substr(replace(total,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(total,'-',''),'.')=length(replace(total,'-',''))-2 AND length(total)-length(replace(total,'-',''))<=1 AND instr(total,'-') IN(0,1) AND (substr(replace(total,'-',''),1,1)!='0' OR instr(replace(total,'-',''),'.')=2) AND total!='-0.00'),status TEXT NOT NULL CHECK(status IN('RESERVED','DISPATCHED')),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,id),UNIQUE(companyId,id,branchId),FOREIGN KEY(companyId,branchId,sku) REFERENCES lab_stock(companyId,branchId,sku)) STRICT;
CREATE TABLE IF NOT EXISTS lab_invoices(companyId TEXT NOT NULL,id TEXT NOT NULL,branchId TEXT NOT NULL,actorId TEXT NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),mode TEXT NOT NULL CHECK(mode IN('CASH','CREDIT','COD')),customerId TEXT,total TEXT NOT NULL CHECK(typeof(total)='text' AND length(replace(total,'-','')) BETWEEN 4 AND 21 AND replace(total,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(total,'-',''))-length(replace(replace(total,'-',''),'.',''))=1 AND substr(replace(total,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(total,'-',''),'.')=length(replace(total,'-',''))-2 AND length(total)-length(replace(total,'-',''))<=1 AND instr(total,'-') IN(0,1) AND (substr(replace(total,'-',''),1,1)!='0' OR instr(replace(total,'-',''),'.')=2) AND total!='-0.00'),returnedQty INTEGER NOT NULL DEFAULT 0 CHECK(returnedQty>=0 AND returnedQty<=quantity),returnedTotal TEXT NOT NULL CHECK(typeof(returnedTotal)='text' AND length(replace(returnedTotal,'-','')) BETWEEN 4 AND 21 AND replace(returnedTotal,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(returnedTotal,'-',''))-length(replace(replace(returnedTotal,'-',''),'.',''))=1 AND substr(replace(returnedTotal,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(returnedTotal,'-',''),'.')=length(replace(returnedTotal,'-',''))-2 AND length(returnedTotal)-length(replace(returnedTotal,'-',''))<=1 AND instr(returnedTotal,'-') IN(0,1) AND (substr(replace(returnedTotal,'-',''),1,1)!='0' OR instr(replace(returnedTotal,'-',''),'.')=2) AND returnedTotal!='-0.00') DEFAULT '0.00',version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,id),UNIQUE(companyId,id,branchId),FOREIGN KEY(companyId,actorId,branchId) REFERENCES lab_actors(companyId,id,branchId),FOREIGN KEY(companyId,branchId,sku) REFERENCES lab_stock(companyId,branchId,sku),FOREIGN KEY(companyId,branchId,customerId) REFERENCES lab_customers(companyId,branchId,id),CHECK(mode!='CREDIT' OR customerId IS NOT NULL)) STRICT;
CREATE TABLE IF NOT EXISTS lab_returns(companyId TEXT NOT NULL,id TEXT NOT NULL,branchId TEXT NOT NULL,invoiceId TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),total TEXT NOT NULL CHECK(typeof(total)='text' AND length(replace(total,'-','')) BETWEEN 4 AND 21 AND replace(total,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(total,'-',''))-length(replace(replace(total,'-',''),'.',''))=1 AND substr(replace(total,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(total,'-',''),'.')=length(replace(total,'-',''))-2 AND length(total)-length(replace(total,'-',''))<=1 AND instr(total,'-') IN(0,1) AND (substr(replace(total,'-',''),1,1)!='0' OR instr(replace(total,'-',''),'.')=2) AND total!='-0.00'),PRIMARY KEY(companyId,id),FOREIGN KEY(companyId,invoiceId,branchId) REFERENCES lab_invoices(companyId,id,branchId)) STRICT;
CREATE TABLE IF NOT EXISTS lab_receipts(companyId TEXT NOT NULL,operation TEXT NOT NULL,branchId TEXT NOT NULL,invoiceId TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('IN','OUT')),amount TEXT NOT NULL CHECK(typeof(amount)='text' AND length(replace(amount,'-','')) BETWEEN 4 AND 21 AND replace(amount,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(amount,'-',''))-length(replace(replace(amount,'-',''),'.',''))=1 AND substr(replace(amount,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(amount,'-',''),'.')=length(replace(amount,'-',''))-2 AND length(amount)-length(replace(amount,'-',''))<=1 AND instr(amount,'-') IN(0,1) AND (substr(replace(amount,'-',''),1,1)!='0' OR instr(replace(amount,'-',''),'.')=2) AND amount!='-0.00'),PRIMARY KEY(companyId,operation),FOREIGN KEY(companyId,operation) REFERENCES lab_operations(companyId,clientRequestId),FOREIGN KEY(companyId,invoiceId,branchId) REFERENCES lab_invoices(companyId,id,branchId)) STRICT;
CREATE TABLE IF NOT EXISTS lab_journal(companyId TEXT NOT NULL,operation TEXT NOT NULL,account TEXT NOT NULL,amount TEXT NOT NULL CHECK(typeof(amount)='text' AND length(replace(amount,'-','')) BETWEEN 4 AND 21 AND replace(amount,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(amount,'-',''))-length(replace(replace(amount,'-',''),'.',''))=1 AND substr(replace(amount,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(amount,'-',''),'.')=length(replace(amount,'-',''))-2 AND length(amount)-length(replace(amount,'-',''))<=1 AND instr(amount,'-') IN(0,1) AND (substr(replace(amount,'-',''),1,1)!='0' OR instr(replace(amount,'-',''),'.')=2) AND amount!='-0.00'),PRIMARY KEY(companyId,operation,account),FOREIGN KEY(companyId,operation) REFERENCES lab_operations(companyId,clientRequestId)) STRICT;
CREATE TABLE IF NOT EXISTS lab_moves(companyId TEXT NOT NULL,operation TEXT NOT NULL,branchId TEXT NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL,reservedDelta INTEGER NOT NULL,PRIMARY KEY(companyId,operation),FOREIGN KEY(companyId,operation) REFERENCES lab_operations(companyId,clientRequestId),FOREIGN KEY(companyId,branchId,sku) REFERENCES lab_stock(companyId,branchId,sku)) STRICT;
CREATE TABLE IF NOT EXISTS lab_audit(companyId TEXT NOT NULL,operation TEXT NOT NULL,details TEXT NOT NULL,PRIMARY KEY(companyId,operation),FOREIGN KEY(companyId,operation) REFERENCES lab_operations(companyId,clientRequestId)) STRICT;
CREATE TABLE IF NOT EXISTS lab_outbox(companyId TEXT NOT NULL,operation TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(companyId,operation),FOREIGN KEY(companyId,operation) REFERENCES lab_operations(companyId,clientRequestId)) STRICT;
CREATE TABLE IF NOT EXISTS lab_wallets(companyId TEXT NOT NULL,branchId TEXT NOT NULL,id TEXT NOT NULL,balance TEXT NOT NULL CHECK(typeof(balance)='text' AND length(replace(balance,'-','')) BETWEEN 4 AND 21 AND replace(balance,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(balance,'-',''))-length(replace(replace(balance,'-',''),'.',''))=1 AND substr(replace(balance,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(balance,'-',''),'.')=length(replace(balance,'-',''))-2 AND length(balance)-length(replace(balance,'-',''))<=1 AND instr(balance,'-') IN(0,1) AND (substr(replace(balance,'-',''),1,1)!='0' OR instr(replace(balance,'-',''),'.')=2) AND balance!='-0.00'),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,branchId,id),FOREIGN KEY(companyId,branchId) REFERENCES lab_branches(companyId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_digital(companyId TEXT NOT NULL,id TEXT NOT NULL,branchId TEXT NOT NULL,walletId TEXT NOT NULL,amount TEXT NOT NULL CHECK(typeof(amount)='text' AND length(replace(amount,'-','')) BETWEEN 4 AND 21 AND replace(amount,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(amount,'-',''))-length(replace(replace(amount,'-',''),'.',''))=1 AND substr(replace(amount,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(amount,'-',''),'.')=length(replace(amount,'-',''))-2 AND length(amount)-length(replace(amount,'-',''))<=1 AND instr(amount,'-') IN(0,1) AND (substr(replace(amount,'-',''),1,1)!='0' OR instr(replace(amount,'-',''),'.')=2) AND amount!='-0.00'),state TEXT NOT NULL CHECK(state IN('CLAIMED','UNKNOWN','CONFIRMED','POSTED')),providerCalls INTEGER NOT NULL CHECK(providerCalls=1),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(companyId,id),FOREIGN KEY(companyId,branchId,walletId) REFERENCES lab_wallets(companyId,branchId,id)) STRICT;
CREATE TABLE IF NOT EXISTS lab_money_probe(id TEXT PRIMARY KEY,amount TEXT NOT NULL CHECK(typeof(amount)='text' AND length(replace(amount,'-','')) BETWEEN 4 AND 21 AND replace(amount,'-','') NOT GLOB '*[^0-9.]*' AND length(replace(amount,'-',''))-length(replace(replace(amount,'-',''),'.',''))=1 AND substr(replace(amount,'-',''),-2) GLOB '[0-9][0-9]' AND instr(replace(amount,'-',''),'.')=length(replace(amount,'-',''))-2 AND length(amount)-length(replace(amount,'-',''))<=1 AND instr(amount,'-') IN(0,1) AND (substr(replace(amount,'-',''),1,1)!='0' OR instr(replace(amount,'-',''),'.')=2) AND amount!='-0.00') CHECK(typeof(amount)='text' AND amount NOT GLOB '*[^0-9.-]*' AND instr(amount,'.')=length(amount)-2 AND length(amount)<=22)) STRICT;
CREATE TABLE IF NOT EXISTS lab_assert(ok INTEGER NOT NULL CHECK(ok=1)) STRICT;
CREATE TABLE IF NOT EXISTS lab_collation_binary(value TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE IF NOT EXISTS lab_collation_nocase(value TEXT NOT NULL COLLATE NOCASE UNIQUE) STRICT;
